import{_ as t,d as a,e as n,x as i}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"Appendix A Human Variable Interface Cards","description":"","frontmatter":{"title":"Appendix A Human Variable Interface Cards","xkChars":0,"xkWords":225},"headers":[],"relativePath":"en/theory/appendix-a/index.md","filePath":"en/theory/appendix-a/index.md"}'),o={name:"en/theory/appendix-a/index.md"};function r(s,e,c,l,d,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<div class="theory-source"><p><a id="part_17"></a></p><h1 id="part-title-17" tabindex="-1">Appendix A Human Variable Interface Cards <a class="header-anchor" href="#part-title-17" aria-label="Permalink to &quot;Appendix A Human Variable Interface Cards {#part-title-17}&quot;">​</a></h1><p>This appendix contains the complete interface cards for the 11 human variables (HV01–HV11) in Part 7. Each card is organized into five sections, A–E. A covers identity, proposition, and scope. B covers formal dependencies and limits on conclusions. C covers the nine-axis scale and object contract.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> D covers state, evidence, and variable flows. E covers uptake, responsibility, normative status, ceilings, and correction.</p><p>The 11 cards below set out all 39 formal fields for each variable. The fields specify the structure of the contract. Collect specific evidence as required by the selected route, taking each item’s relevance to the task into account. Record inapplicability, unknowns, material not yet collected, and material unavailable for reasons of protection separately. Completing the form is no prerequisite for ordinary services or understanding. An empty dependency set is explicitly written as “None (empty set).” It means only that nothing is registered for that kind of dependency. It does not establish that evidence is sufficient or that an empirical claim holds. Read each conditional support route as a whole. Favorable conditions from different routes must not be combined after the fact.</p></div><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Translator&#39;s note: A contract here is an analytical agreement registered and frozen before results, akin to pre-registration. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',3)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
